74: export class SelectionStatisticsError extends Error {
75:   constructor(
76:     message: string,
77:     readonly code: "invalid_input" | "database_error",
78:     options?: ErrorOptions,
79:   ) {
80:     super(message, options);
81:     this.name = "SelectionStatisticsError";
82:   }
